SELECT event_transmission_result_id, event_occured_id, detector_proc_id, tracking_process_id, request_tracking_id, event_transmission_status, transmission_url, transmission_param, event_occured_msg, transmission_time, transmission_resp_code, transmission_resp_msg FROM event_transmission_result_info WHERE 1=1
AND event_transmission_result_id = #{evnetTransMissionResultId}
ORDER BY event_transmission_result_id DESC
